function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true"><path d="${ICONS[name]||ICONS.book}"/></svg>`;}
function esc(v){return String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function safeUrl(value){try{const u=new URL(String(value).replace(/\\&/g,'&'));return ['https:','http:'].includes(u.protocol)?u.href:'';}catch{return '';}}
function inline(text,base='https://www.churchofjesuschrist.org'){
 const source=String(text),links=ReferenceEngine.extractLinks(source,base);
 const format=t=>esc(t.replace(/\\([~&*_[\]()>])/g,'$1')).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>');
 let out='',pos=0;
 for(const l of links){out+=format(source.slice(pos,l.start));out+=`<a href="#reference" data-ref-url="${esc(l.sourceURL)}" title="참조자료 읽기 / Read reference">${format(l.label)}</a>`;pos=l.end;}
 return out+format(source.slice(pos));
}
function markdown(text){
 const s=String(text).trim();const h=s.match(/^(#{1,3})\s+([\s\S]*)$/);
 if(h)return `<h${h[1].length}>${inline(h[2])}</h${h[1].length}>`;
 if(/^[-*] /.test(s))return `<ul>${s.split(/\n(?=[-*] )/).map(x=>`<li>${inline(x.replace(/^[-*] /,''))}</li>`).join('\n')}</ul>`;
 return `<p>${inline(s).replace(/\n/g,'<br>')}</p>`;
}
function plain(md){const d=document.createElement('div');d.innerHTML=markdown(md);return d.textContent;}
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0).toString(16).padStart(8,'0');}
function uid(){return typeof crypto.randomUUID==='function'?crypto.randomUUID():`local-${Date.now()}-${Math.random().toString(16).slice(2)}`;}
function iso(){return new Date().toISOString();}
function blockText(lesson,blockId,lang){const b=lesson.blocks.find(b=>b.id===blockId);return b?plain(b[lang]||b.ko):'';}
function sampleAnchor(blockId,quote,lang='ko'){
 const b=BASE.blocks.find(b=>b.id===blockId),text=blockText(BASE,blockId,lang),start=text.indexOf(quote);
 if(start<0)throw Error('Seed quote is not present: '+blockId);
 return {lessonKey:BASE.id+'@'+BASE.version,lessonId:BASE.id,version:BASE.version,language:lang,sectionId:b.sectionId,sourceUrl:BASE.sourceUrl[lang],mode:'selection',quote,segments:[{blockId,conceptId:b.conceptId,start,end:start+quote.length,exact:quote,prefix:text.slice(Math.max(0,start-32),start),suffix:text.slice(start+quote.length,start+quote.length+32)}],offsetEncoding:'UTF-16 code units',confidence:'exact'};
}
