function openComposer(anchor,{edit=null,resume=false,forceNew=false}={}){
 if(!anchor&&!resume&&!edit){toast(tr('기록을 연결할 원문을 먼저 선택해 주세요.','Select a source passage first.'),true);return;}
 let restored=false;
 if(edit){composer={id:edit.id,editId:edit.id,anchor:structuredClone(edit.anchor),body:edit.body,type:edit.type,scope:edit.scope,consent:edit.consent,captureWanted:!!edit.snapshot,snapshot:edit.snapshot||null,capturePending:false};}
 else if((resume||(!forceNew&&state.draft))&&state.draft){pendingNewAnchor=anchor;composer={...structuredClone(state.draft),capturePending:false};restored=true;}
 else{composer={id:uid(),editId:null,anchor:structuredClone(anchor),body:'',type:'insight',scope:'private',consent:false,captureWanted:state.view==='read',snapshot:null,capturePending:state.view==='read'};}
 const a=composer.anchor,l=lessonForAnchor(a)||currentLesson();
 const capturePromise=composer.capturePending?captureReadingRegion(a):null;
 const kindLabel=({selection:tr('선택한 문장','Selected passage'),paragraph:tr('이 문단','This paragraph'),viewport:tr('지금 읽는 문단','Current paragraph'),external:tr('공유된 인용문 · 위치 미확인','Shared quotation · position unverified')})[a.mode]||tr('연결된 문장','Linked passage');
 const content=modalHead(edit?tr('인사이트 수정','Edit reflection'):tr('마음에 남은 생각','A thought worth keeping'),tr('인용문과 원문 위치를 함께 기록합니다.','Your quotation and its location stay with your reflection.'))+`<div class="modal-body">${restored?`<div class="draft-banner"><span>${tr('이전에 쓰던 임시 기록을 복원했습니다.','Your unfinished reflection has been restored.')}</span>${pendingNewAnchor?`<button class="text-btn" data-action="fresh-composer">${tr('새로 쓰기','Start a new one')}</button>`:''}</div>`:''}<div class="composer-grid"><aside class="context-column"><div class="context-label">${icon('quote')}<strong>${kindLabel}</strong><span class="pill gray">${a.language==='ko'?'한국어':'EN'}</span></div><div class="context-path">${esc(l.title[a.language]||l.title.ko)}<br>${esc(sectionName(a.sectionId,a.language,l))}</div><blockquote class="context-quote">${esc(a.quote)}</blockquote><div class="context-meta">${a.segments?.length?`${tr('문단','Block')} ${a.segments.map(s=>esc(s.blockId)).join(' · ')}<br>${tr('원문 버전','Version')} ${esc(a.version)} · ${tr('위치와 인용문 함께 보존','Position and quotation preserved')}`:tr('정확한 위치는 확인되지 않았습니다. 공유된 링크와 인용문만 보관합니다.','Exact location not verified. Only the shared link and quotation are kept.')}</div><button class="text-btn" data-action="anchor-details">${icon('link','small')}${tr('저장되는 위치 정보','View saved location data')}</button><div class="snapshot-wrap" id="snapshotSlot">${currentComposerSnapshotHTML()}</div></aside><section><div class="composer-prompt">${tr('어떤 생각을 기록하고 싶으신가요?','What would you like to remember?')}</div><div class="composer-type" role="group" aria-label="${tr('기록 종류','Reflection type')}">${['insight','question','application'].map(t=>`<button data-composer-type="${t}" class="${composer.type===t?'active':''}" aria-pressed="${composer.type===t}">${typeLabel(t)}</button>`).join('')}</div><label for="insightText" class="composer-prompt" style="display:block">${tr('나의 인사이트','My reflection')}</label><textarea class="composer-text" id="insightText" maxlength="${MAX_TEXT}" placeholder="${tr('이 말씀에서 무엇을 배웠나요?\n나의 경험, 질문, 이번 주의 작은 실천을 남겨 보세요.','What did you learn from this passage?\nWrite a thought, a question, or a small step for the week.')}">${esc(composer.body)}</textarea><div class="composer-count"><span id="draftStatus">${tr('저장 전까지 다른 사람에게 보이지 않습니다.','Not shared until you save.')}</span><span id="textCount">${composer.body.length} / ${MAX_TEXT}</span></div><div id="composerError" class="alert error" hidden role="alert"></div><div class="scope-title">${tr('누구와 나눌까요?','Who can see this?')}</div><div class="scope-options"><button class="scope-choice ${composer.scope==='private'?'active':''}" data-composer-scope="private" aria-pressed="${composer.scope==='private'}">${icon('lock')}<span><strong>${tr('나만 보기','Only me')}</strong><small>${tr('개인 기록','Private reflection')}</small></span></button><button class="scope-choice ${composer.scope==='class'?'active':''}" data-composer-scope="class" aria-pressed="${composer.scope==='class'}">${icon('people')}<span><strong>${tr('반원들과 나눔','Share with class')}</strong><small>${tr('초대받은 반원','Invited class members')}</small></span></button></div><label class="checkline" style="margin-top:14px"><input id="classConsent" type="checkbox" ${composer.consent?'checked':''} ${composer.scope==='private'?'disabled':''}><span>${tr('주일학교 발표 화면에서도 나눠도 좋아요.','This may also be shown during Sunday School.')}</span></label><p class="tiny muted" style="margin-bottom:0">${tr('공유해도 발표에는 별도 동의가 필요합니다. 나중에 변경할 수 있어요.','Sharing does not automatically permit presentation. You can change this later.')}</p></section></div></div><footer class="modal-footer"><span class="privacy-line">${icon('lock','small')} ${tr('이 브라우저에만 저장 · 실제 전송 없음','Saved in this browser only · not sent')}</span><div class="buttons"><button class="btn quiet" data-action="save-draft">${tr('나중에 이어 쓰기','Continue later')}</button><button class="btn primary" data-action="save-insight">${icon('check')}${tr('기록 저장','Save reflection')}</button></div></footer>`;
 const token=showModal(content,{kind:'composer'});$('#insightText').focus({preventScroll:true});
 if(capturePromise)capturePromise.then(snapshot=>{if(modalSession!==token||!composer)return;composer.capturePending=false;if(composer.captureWanted)composer.snapshot=snapshot;$('#snapshotSlot').innerHTML=currentComposerSnapshotHTML();if(composer.body.trim())storeDraft();});
}
function composerScope(scope){if(!composer)return;composer.scope=scope;if(scope==='private')composer.consent=false;$$('[data-composer-scope]',$('#modal')).forEach(el=>{const active=el.dataset.composerScope===scope;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});$('#classConsent').disabled=scope==='private';$('#classConsent').checked=composer.consent;storeDraft();}
function composerType(type){if(!composer)return;composer.type=type;$$('[data-composer-type]',$('#modal')).forEach(el=>{const active=el.dataset.composerType===type;el.classList.toggle('active',active);el.setAttribute('aria-pressed',String(active));});storeDraft();}
function saveInsight(){if(!composer)return;const value=$('#insightText').value.trim();if(!value){$('#composerError').textContent=tr('인사이트 내용을 한 글자 이상 입력해 주세요.','Please enter a reflection before saving.');$('#composerError').hidden=false;$('#insightText').setAttribute('aria-invalid','true');$('#insightText').focus();return;}if(composer.capturePending&&composer.captureWanted){toast(tr('이미지를 만드는 중입니다. 잠시 기다리거나 ‘첨부 제외’를 선택해 주세요.','The image is rendering. Please wait, or choose Omit.'));return;}
 const existing=state.notes.find(n=>n.id===composer.editId);const note={...(existing||{}),id:existing?.id||composer.id,owner:'me',author:tr('나','Me'),demo:false,language:existing?.language||composer.anchor.language,body:value,type:composer.type,scope:composer.scope,consent:composer.scope==='class'&&$('#classConsent').checked,anchor:composer.anchor,snapshot:composer.captureWanted?composer.snapshot:null,likes:existing?.likes||[],comments:existing?.comments||[],created:existing?.created||iso(),updated:iso()};
 if(existing){state.notes[state.notes.indexOf(existing)]=note;}else state.notes.unshift(note);
 if(state.draft?.id===composer.id)state.draft=null;cleanQueue();const ok=saveState();closeModal(false);refreshPreservingScroll();clearSelection();toast(ok?(note.scope==='class'?tr('반원 공유 피드에 반영했습니다. 이 브라우저의 데모에서만 보입니다.','Added to the class feed in this local demo only.'):tr('나만 보는 기록으로 저장했습니다.','Saved as a private reflection.')):tr('메모리에만 남아 있습니다. JSON 내보내기로 보관해 주세요.','Kept in memory only. Export JSON to preserve it.'),!ok);
}
function showThread(id){const n=state.notes.find(n=>n.id===id);if(!n)return;if(n.scope==='private'){toast(tr('비공개 기록에는 반원 댓글을 달 수 없습니다.','Class replies are not available on private notes.'),true);return;}showModal(modalHead(tr('함께 나누는 생각','A conversation around the passage'),tr('인용문을 중심으로 서로의 배움을 나눠 보세요.','Share what you are learning, with the passage in view.'))+`<div class="modal-body">${noteCard(n)}<div class="thread-context-note">${tr('댓글은 이 인사이트와 동일한 반원 공개 범위를 따릅니다. 실제 전송은 하지 않습니다.','Replies follow the same class visibility as this reflection. Nothing is sent remotely.')}</div><div id="threadReplies">${repliesHTML(n)}</div><label for="replyText" class="composer-prompt" style="display:block;margin-top:15px">${tr('댓글 남기기','Add a reply')}</label><div class="reply-input"><textarea id="replyText" maxlength="1500" placeholder="${tr('생각을 나누거나 질문해 보세요.','Share a thought or ask a question.')}"></textarea><button class="btn primary" data-action="send-reply" data-id="${id}">${tr('등록','Reply')}</button></div><div id="replyError" class="alert error" hidden style="margin-top:10px" role="alert"></div></div>`,{kind:'thread',size:'medium'});}
function repliesHTML(n){return `<div class="section-row"><h2>${tr('댓글','Replies')} ${n.comments.length}</h2><small>${tr('이 브라우저의 데모','Local demo')}</small></div>${window.TogetherDiscussion.commentsHTML(n.comments)}`;}
function sendReply(id){const n=state.notes.find(n=>n.id===id),input=$('#replyText'),body=input?.value.trim();if(!n||n.scope!=='class')return;if(!body){$('#replyError').textContent=tr('댓글 내용을 입력해 주세요.','Please enter a reply.');$('#replyError').hidden=false;input.focus();return;}n.comments.push({id:uid(),owner:'me',author:'나',body,created:iso(),demo:false});saveState();$('#threadReplies').innerHTML=repliesHTML(n);input.value='';$('#replyError').hidden=true;refreshPreservingScroll();toast(tr('댓글을 데모에 반영했습니다. 실제 전송은 하지 않았습니다.','Reply added to the demo; nothing was sent remotely.'));}
function showBlockNotes(blockId){const ns=sharedNotes().filter(n=>n.anchor.segments?.some(s=>s.blockId===blockId));showModal(modalHead(tr('이 문단에 남긴 생각','Thoughts on this passage'),tr('같은 원문에서 시작된 대화입니다.','A conversation connected to the same passage.'))+`<div class="modal-body">${ns.map(n=>noteCard(n)).join('')}<button class="btn primary full" data-action="compose-from-modal" data-block="${blockId}">${icon('spark')}${tr('나도 인사이트 남기기','Add my reflection')}</button></div>`,{kind:'block-notes',size:'medium'});}
function showAbout(){showModal(modalHead(tr('함께 · 인터랙티브 프로토타입','Together · interactive prototype'),tr('공식 교회 앱이 아닌, 학습·나눔 흐름을 검토하기 위한 시제품입니다.','An unofficial prototype for evaluating the study and sharing flow.'))+`<div class="modal-body"><div class="panel"><h2>${tr('작동하는 기능','Working interactions')}</h2><p class="help">${tr('첨부본 읽기, 한국어/영어 전환, 오른쪽 성구 패널, 성구·공과 형광펜, 선택 위치 저장, 읽기 영역 이미지 + 생각, 인사이트·댓글·공감, 내 기록, 발표 동의와 나눔 보드, Markdown 입력, JSON 내보내기.','Lesson reading, Korean/English switching, a scripture side panel, verse and lesson highlights, precise source anchors, source-image reflections, replies/reactions, a personal journal, consent-aware classroom mode, Markdown input, and JSON export.')}</p><h2>${tr('연결되지 않은 기능','Not connected')}</h2><p class="help">${tr('실제 사용자 계정, 서버 데이터베이스, 여러 기기 동기화, 자동 번역 서비스, 배포·회원 초대. 역할과 공개 범위는 화면 시뮬레이션입니다.','Real accounts, a server database, cross-device synchronization, an automatic translation service, hosting, and member invitations. Roles and visibility are UI simulations.')}</p></div><div class="alert">${tr('한국어 본문은 업로드한 자료에서 가져왔습니다. 영어는 그 한국어의 시연용 번역이며 공식 영문판이 아닙니다. 이미지·활동지는 원본 링크로 보존합니다. 자료를 실제 서비스에 재게시하기 전에 이용 권한을 확인해야 합니다.','The Korean text comes from the supplied file. English is a prototype translation, not the official edition. Artwork and activity sheets remain original links. Verify reuse permissions before publishing the material in a real service.')}</div><p class="notice-foot">${tr('나만 보기 선택은 서버 보안이 아닙니다. 기록은 암호화되지 않은 로컬 브라우저 저장소에 남습니다. 샘플 성도와 샘플 경험은 모두 가상입니다.','The Private choice is not server security. Notes are stored unencrypted in this browser. All sample members and experiences are fictional.')}</p></div>`,{kind:'about',size:'medium'});}
function parseImportBlocks(raw){
 const chunks=String(raw).replace(/\r\n?/g,'\n').trim().split(/\n\s*\n/);let section='intro',sections=[{id:'intro',ko:'공과 소개',en:'Lesson introduction'}],occ=new Map(),headings=new Map(),blocks=[];
 for(let text of chunks){text=text.replace(/^(#{1,3}\s*|-\s*)?svg(?=[“"가-힣]|$)/gm,'$1').trim();if(!text||/^#{1,3}$/.test(text))continue;const h=text.match(/^(#{2,3})\s+(.+)$/);if(h){const name=plain(h[2]),key=hash(name),count=(headings.get(key)||0)+1;headings.set(key,count);section=`s-${key}-${count}`;sections.push({id:section,ko:name,en:name});}const digest=hash(text),num=(occ.get(digest)||0)+1;occ.set(digest,num);let kind='text';if(/^\[[^\]]+\]\(https?:\/\/[^)]+\/imgs\//.test(text))kind='media';blocks.push({id:`b-${digest}-${num}`,sectionId:section,kind,raw:text});}
 return {blocks,sections};
}
function bindFileInputs(){window.TogetherImporter?.bind();}
function previewImport(){return window.TogetherImporter?.review();}
function applyImport(){return window.TogetherImporter?.publish();}
function toggleLike(id){const n=state.notes.find(n=>n.id===id);if(!n||n.scope!=='class')return;const at=n.likes.indexOf('me');if(at>=0)n.likes.splice(at,1);else n.likes.push('me');saveState();refreshPreservingScroll();if(modalKind==='thread'){const note=$('.modal .note-card');if(note)note.outerHTML=noteCard(n);}}
function toggleQueue(id){const n=state.notes.find(n=>n.id===id);if(state.role!=='teacher'){toast(tr('교사 보기에서 체험할 수 있습니다.','Try this in Teacher view.'));return;}if(!eligible(n)){toast(tr('반원 공유와 발표 동의가 모두 필요합니다.','Class sharing and presentation consent are both required.'),true);return;}const idx=state.queue.indexOf(id);if(idx>=0)state.queue.splice(idx,1);else state.queue.push(id);saveState();refreshPreservingScroll();toast(idx>=0?tr('나눔 보드에서 뺐습니다.','Removed from the sharing board.'):tr('나눔 보드에 담았습니다.','Added to the sharing board.'));}
function moveQueue(id,delta){if(state.role!=='teacher')return;const q=queueNotes(),i=q.findIndex(n=>n.id===id),other=q[i+delta];if(i<0||!other)return;const a=state.queue.indexOf(id),b=state.queue.indexOf(other.id);[state.queue[a],state.queue[b]]=[state.queue[b],state.queue[a]];saveState();refreshPreservingScroll();}
function startPresentation(){if(state.role!=='teacher'||!queueNotes().length)return;presentationIndex=0;showNames=false;$('#presentation').hidden=false;$('#app').inert=true;$('#floatingInsight').hidden=true;$('#floatingHint').hidden=true;document.body.classList.add('modal-lock');renderPresentation();$('#presentation button')?.focus();}
function renderPresentation(){const q=queueNotes();if(!q.length){endPresentation();return;}presentationIndex=Math.max(0,Math.min(presentationIndex,q.length-1));const n=q[presentationIndex];$('#presentation').innerHTML=`<div class="presentation-top"><span>${tr('함께 · 주일학교 나눔','Together · Sunday School')}<br><span class="tiny">${tr('발표 동의된 기록만','Only author-approved reflections')}</span></span><div class="buttons"><button class="btn sm quiet" data-action="present-language">${lang()==='ko'?'English':'한국어'}</button><button class="btn sm quiet" data-action="present-names">${icon('eye')}${showNames?tr('이름 숨기기','Hide names'):tr('이름 표시','Show names')}</button><button class="btn sm" data-action="present-close">${icon('close')}${tr('마치기','Exit')}</button></div></div><article class="presentation-content"><div class="eyebrow">${esc(sectionName(n.anchor.sectionId))} · ${typeLabel(n.type)}</div><blockquote>${esc(noteQuote(n))}</blockquote><div class="insight-text">${esc(noteBody(n))}</div><div class="author">${showNames?avatar(n):icon('people')}<span>${showNames?esc(authorName(n)):tr('한 반원의 인사이트','A class member’s reflection')}${n.demo?` · ${tr('예시','Example')}`:''}</span></div></article><footer class="presentation-bottom"><span>${tr('← → 이동 · Esc 마치기','← → Navigate · Esc to exit')}</span><div class="controls"><button class="btn sm" data-action="present-prev" ${presentationIndex===0?'disabled':''} aria-label="${tr('이전 기록','Previous reflection')}">${icon('back')}</button><span>${String(presentationIndex+1).padStart(2,'0')} / ${String(q.length).padStart(2,'0')}</span><button class="btn sm" data-action="present-next" ${presentationIndex===q.length-1?'disabled':''} aria-label="${tr('다음 기록','Next reflection')}">${icon('arrow')}</button></div></footer>`;}
function endPresentation(){$('#presentation').hidden=true;$('#presentation').innerHTML='';$('#app').inert=false;document.body.classList.remove('modal-lock');render();$('#app [data-action="present"]')?.focus();}
function exportNotes(){const notes=ownNotes(),keys=new Set(notes.map(n=>n.anchor.lessonKey));if(state.draft)keys.add(state.draft.anchor.lessonKey);const payload={schema:'together-insights-export-v1',exportedAt:iso(),notice:'Private browser-local data. Not encrypted. Contains original quotations, lesson snapshots, and captured images. Do not publish without reviewing privacy and content rights.',notes,draft:state.draft,lessons:lessons().filter(l=>keys.has(lessonKey(l)))};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='my-insights-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),2000);toast(tr('내보내기에는 비공개 기록이 포함됩니다. 안전하게 보관해 주세요.','The export contains private reflections. Store it securely.'));}
function deleteNote(id){const n=state.notes.find(n=>n.id===id);if(!n||n.owner!=='me')return;if(!confirm(tr('이 기록과 그 댓글을 삭제할까요? 이 작업은 되돌릴 수 없습니다.','Delete this reflection and its replies? This cannot be undone.')))return;state.notes=state.notes.filter(n=>n.id!==id);cleanQueue();saveState();refreshPreservingScroll();toast(tr('기록을 삭제했습니다.','Reflection deleted.'));}
function detailsToggle(){if(!composer)return;const existing=$('#anchorDetails');if(existing){existing.remove();return;}const el=document.createElement('pre');el.id='anchorDetails';el.className='source-detail';el.textContent=JSON.stringify(composer.anchor,null,2);$('.context-column').append(el);}
function zoomCapture(){if(!composer?.snapshot)return;const d=document.createElement('dialog');d.className='modal wide';d.innerHTML=modalHead(tr('읽기 영역 이미지','Reading-area image'),tr('원문 텍스트의 DOM 렌더 이미지입니다.','This is a DOM-rendered image of lesson text.')).replace('data-action="modal-close"','data-action="image-close"')+`<div class="modal-body"><img src="${composer.snapshot.data}" style="display:block;width:100%;height:auto" alt="${tr('기록 시점의 원문','Source text at the time of reflection')}"></div>`;d.addEventListener('close',()=>d.remove());document.body.append(d);d.showModal();}
async function restoreCapture(){if(!composer||(state.view!=='read'&&!reference.open)){toast(tr('공과 읽기 화면에서만 읽기 영역 이미지를 만들 수 있습니다.','Reading-area images are available from the lesson view.'));return;}composer.captureWanted=true;composer.capturePending=true;$('#snapshotSlot').innerHTML=currentComposerSnapshotHTML();const token=modalSession,result=await captureReadingRegion(composer.anchor);if(token!==modalSession||!composer)return;composer.capturePending=false;if(composer.captureWanted)composer.snapshot=result;$('#snapshotSlot').innerHTML=currentComposerSnapshotHTML();storeDraft();}
document.addEventListener('pointerdown',event=>{if(event.target.closest('#floatingInsight,#selectionToolbar'))event.preventDefault();});
document.addEventListener('selectionchange',()=>{clearTimeout(window._selectionDebounce);window._selectionDebounce=setTimeout(selectionChanged,75);});
document.addEventListener('click',event=>{
 const btn=event.target.closest('button,[data-action]');if(!btn||btn.disabled)return;
 if(btn.dataset.nav){navigate(btn.dataset.nav);return;}
 if(btn.dataset.lang){setLanguage(btn.dataset.lang);return;}
 if(btn.dataset.myScope){state.myScope=btn.dataset.myScope;saveState();render();return;}
 if(btn.dataset.composerType){composerType(btn.dataset.composerType);return;}
 if(btn.dataset.composerScope){composerScope(btn.dataset.composerScope);return;}
 const action=btn.dataset.action,id=btn.dataset.id;
 switch(action){
  case 'menu-open':$('#sidebar').classList.add('open');$('#menuBackdrop').classList.add('active');break;
  case 'menu-close':$('#sidebar').classList.remove('open');$('#menuBackdrop').classList.remove('active');break;
  case 'about':showAbout();break;
  case 'insight':case 'selection-insight':openComposer(selectedAnchor||anchorFromSelection()||visibleAnchor());break;
  case 'clear-selection':clearSelection();break;
  case 'demo-select':trySelection();break;
  case 'block-insight':openComposer(anchorForBlock(btn.dataset.block));break;
  case 'block-notes':showBlockNotes(btn.dataset.block);break;
  case 'compose-from-modal':{const a=anchorForBlock(btn.dataset.block);closeModal();openComposer(a);break;}
  case 'modal-close':closeModal();break;
  case 'image-close':btn.closest('dialog').close();break;
  case 'save-insight':saveInsight();break;
  case 'save-draft':{const has=!!$('#insightText')?.value.trim();closeModal(true);refreshPreservingScroll();if(has)toast(tr('임시 기록을 저장했습니다. 내 기록에서 이어 쓸 수 있어요.','Draft saved. Continue from My journal.'));break;}
  case 'resume-draft':openComposer(null,{resume:true});break;
  case 'fresh-composer':{if(!pendingNewAnchor)return;if(!confirm(tr('기존 임시 기록을 지우고 새 문장으로 시작할까요?','Discard the unfinished draft and start with the new passage?')))return;const a=pendingNewAnchor;state.draft=null;closeModal(false);saveState();openComposer(a,{forceNew:true});break;}
  case 'anchor-details':detailsToggle();break;
  case 'remove-capture':if(composer){composer.captureWanted=false;composer.snapshot=null;$('#snapshotSlot').innerHTML=currentComposerSnapshotHTML();storeDraft();}break;
  case 'restore-capture':restoreCapture();break;
  case 'zoom-capture':zoomCapture();break;
  case 'like':toggleLike(id);break;
  case 'thread':showThread(id);break;
  case 'send-reply':sendReply(id);break;
  case 'source':{const n=state.notes.find(n=>n.id===id);if(n){if($('#modal').open)closeModal();goToAnchor(n.anchor);}break;}
  case 'edit-note':{const n=state.notes.find(n=>n.id===id&&n.owner==='me');if(n)openComposer(n.anchor,{edit:n});break;}
  case 'delete-note':deleteNote(id);break;
  case 'queue-toggle':toggleQueue(id);break;
  case 'queue-up':moveQueue(id,-1);break;
  case 'queue-down':moveQueue(id,1);break;
  case 'present':startPresentation();break;
  case 'present-next':presentationIndex++;renderPresentation();break;
  case 'present-prev':presentationIndex--;renderPresentation();break;
  case 'present-close':endPresentation();break;
  case 'present-names':showNames=!showNames;renderPresentation();break;
  case 'present-language':state.language=lang()==='ko'?'en':'ko';saveState();renderPresentation();break;
  case 'export':exportNotes();break;
  case 'preview-import':previewImport();break;
  case 'apply-import':applyImport();break;
  case 'font-smaller':state.fontSize=Math.max(14,state.fontSize-1);document.documentElement.style.setProperty('--reader-size',state.fontSize+'px');saveState();break;
  case 'font-larger':state.fontSize=Math.min(24,state.fontSize+1);document.documentElement.style.setProperty('--reader-size',state.fontSize+'px');saveState();break;
 }
});
document.addEventListener('input',event=>{
 if(event.target.id==='insightText'&&composer){composer.body=event.target.value;$('#textCount').textContent=`${composer.body.length} / ${MAX_TEXT}`;$('#insightText').removeAttribute('aria-invalid');$('#composerError').hidden=true;$('#draftStatus').textContent=tr('입력 중…','Typing…');clearTimeout(draftTimer);draftTimer=setTimeout(()=>{storeDraft();const el=$('#draftStatus');if(el)el.textContent=storageOK?tr('이 브라우저에 임시 저장됨','Draft saved in this browser'):tr('저장 실패 · 입력 내용은 화면에 남아 있어요.','Storage failed · your text is still here.');},800);}
 if(event.target.id==='feedSearch'){state.filters.query=event.target.value;$('#feedResults').innerHTML=feedResultsHTML();}
 if(['importKO','importEN'].includes(event.target.id)){importPreview=null;}
});
document.addEventListener('change',event=>{
 const el=event.target;
 if(el.id==='toc'&&el.value){$(`#readerCard .passage[data-section="${el.value}"]`)?.scrollIntoView({behavior:'smooth',block:'start'});el.value='';}
 if(el.id==='demoRole'){state.role=el.value;saveState();refreshPreservingScroll();}
 if(['filterType','filterLang','filterSection'].includes(el.id)){state.filters[({filterType:'type',filterLang:'lang',filterSection:'section'})[el.id]]=el.value;$('#feedResults').innerHTML=feedResultsHTML();saveState();}
 if(el.id==='classConsent'&&composer){composer.consent=el.checked;storeDraft();}
 if(el.id==='lessonPicker'){state.activeLesson=el.value;state.filters={query:'',type:'all',lang:'all',section:'all'};state.language='ko';currentSection='intro';saveState();render();}
});
$('#modal').addEventListener('cancel',event=>{event.preventDefault();closeModal();});
document.addEventListener('keydown',event=>{if(!$('#presentation').hidden){if(event.key==='ArrowRight'){event.preventDefault();presentationIndex++;renderPresentation();}else if(event.key==='ArrowLeft'){event.preventDefault();presentationIndex--;renderPresentation();}else if(event.key==='Escape'){event.preventDefault();endPresentation();}}});
window.addEventListener('scroll',()=>{if(!$('#selectionToolbar').hidden)$('#selectionToolbar').hidden=true;updateProgress();},{passive:true});
window.addEventListener('beforeunload',()=>{if(modalKind==='composer')storeDraft();});
window.addEventListener('storage',event=>{if(event.key===STORE)toast(tr('다른 탭의 변경이 있습니다. 새로고침 전 현재 기록을 저장하거나 내보내세요. 여러 탭 동시 편집은 지원하지 않습니다.','Another tab changed its data. Save or export your current work before reloading. Concurrent-tab editing is not supported.'),true);});
render();
// Introspection for repeatable local UI tests, not a remote API.
window.TogetherPrototype={getState:()=>state,getLesson:currentLesson,anchorFromSelection,resolveSegment,parseImportBlocks,saveState};
